with metrics as (select *, sum(pressure) over (partition by device_code order by status_bits, id rows between unbounded preceding and current row) as running_pressure, last_value(humidity, true) over (partition by device_code order by temp_c, id rows between unbounded preceding and current row) as last_known_humidity, first_value(pressure) ignore nulls over (order by reading_ts, id rows between unbounded preceding and current row) as first_known_pressure, dense_rank() over (order by pressure nulls last) as pressure_dense_rank, lead(temp_c, 1) over (partition by device_code order by status_bits, id) as next_temp_c from device_readings) select date_trunc('day', reading_ts) as activity_day, max(reading_ts) as last_seen, corr(pressure, temp_c) as corr_pressure_temp_c from metrics group by 1 having corr_pressure_temp_c > 0 order by corr_pressure_temp_c
